def solution(text: str) -> str:
    """Returns the input string with each alphabetic character rotated by 13 positions (ROT13)."""
    result = []
    for c in text:
        if 'a' <= c <= 'z':
            result.append(chr(((ord(c) - ord('a') + 13) % 26) + ord('a')))
        elif 'A' <= c <= 'Z':
            result.append(chr(((ord(c) - ord('A') + 13) % 26) + ord('A')))
        else:
            result.append(c)
    return ''.join(result)
